'use strict';
// Shared, data-independent map interaction: anchored zoom, bounded pan and pinch.
class MapNavigation{
 constructor(root,scene,{onInspect=()=>{},onChange=()=>{},enabled=()=>true,maxZoom=12}={}){this.root=root;this.scene=scene;this.onInspect=onInspect;this.onChange=onChange;this.enabled=enabled;this.maxZoom=maxZoom;this.z=1;this.x=0;this.y=0;this.points=new Map();this.gesture=null;this.size=null;this.suppressTap=false;root.style.touchAction='none';scene.querySelectorAll('img').forEach(i=>{i.draggable=false;});
 root.addEventListener('pointerdown',e=>this.down(e));root.addEventListener('pointermove',e=>this.move(e));root.addEventListener('pointerup',e=>this.up(e));root.addEventListener('pointercancel',e=>this.cancel(e));root.addEventListener('lostpointercapture',e=>this.cancel(e));root.addEventListener('dragstart',e=>e.preventDefault());root.addEventListener('dblclick',e=>{if(!e.target.closest('button')&&this.enabled()){e.preventDefault();this.zoomTo(this.z*2,e.clientX,e.clientY);}});
 root.addEventListener('wheel',e=>{if(!this.enabled())return;e.preventDefault();if(e.shiftKey||Math.abs(e.deltaX)>1&&!e.ctrlKey)this.pan(-(e.deltaX||e.deltaY),e.shiftKey?0:-e.deltaY);else this.zoomTo(this.z*Math.exp(-e.deltaY*(e.ctrlKey?.01:.002)),e.clientX,e.clientY);},{passive:false});root.addEventListener('keydown',e=>{if(e.target!==root||!this.enabled())return;const r=root.getBoundingClientRect(),actions={'+':()=>this.zoomTo(this.z*1.5),'=':()=>this.zoomTo(this.z*1.5),'-':()=>this.zoomTo(this.z/1.5),'Home':()=>this.reset(),'Escape':()=>this.reset(),'ArrowLeft':()=>this.pan(r.width*.15,0),'ArrowRight':()=>this.pan(-r.width*.15,0),'ArrowUp':()=>this.pan(0,r.height*.15),'ArrowDown':()=>this.pan(0,-r.height*.15),'Enter':()=>this.onInspect(r.left+r.width/2,r.top+r.height/2)};if(actions[e.key]){e.preventDefault();actions[e.key]();}});
 this.observer=new ResizeObserver(()=>{const r=root.getBoundingClientRect();if(r.width<1||r.height<1)return;if(this.size){this.x*=r.width/this.size.w;this.y*=r.height/this.size.h;}this.size={w:r.width,h:r.height};this.apply();});this.observer.observe(root);this.apply();}
 local(x,y){const r=this.root.getBoundingClientRect();return {x:x-r.left-r.width/2,y:y-r.top-r.height/2};}
 apply(){const r=this.root.getBoundingClientRect();if(r.width<1||r.height<1)return;this.z=Math.max(1,Math.min(this.maxZoom,this.z));const mx=r.width*(this.z-1)/2,my=r.height*(this.z-1)/2;this.x=Math.max(-mx,Math.min(mx,this.x));this.y=Math.max(-my,Math.min(my,this.y));this.scene.style.transform=`translate(${this.x}px,${this.y}px) scale(${this.z})`;this.root.classList.toggle('zoomed',this.z>1);this.onChange({zoom:this.z,panX:this.x,panY:this.y});}
 setView(z,x=0,y=0){this.z=z;this.x=x;this.y=y;this.apply();}reset(){this.setView(1,0,0);}
 zoomTo(z,cx,cy){const r=this.root.getBoundingClientRect();cx??=r.left+r.width/2;cy??=r.top+r.height/2;const q=this.local(cx,cy),target=Math.max(1,Math.min(this.maxZoom,z)),ratio=target/this.z;this.x=q.x-(q.x-this.x)*ratio;this.y=q.y-(q.y-this.y)*ratio;this.z=target;this.apply();}
 pan(dx,dy){if(!this.enabled())return;this.x+=dx;this.y+=dy;this.apply();}
 begin(){const p=[...this.points.values()];if(p.length>=2){const mid={x:(p[0].x+p[1].x)/2,y:(p[0].y+p[1].y)/2},q=this.local(mid.x,mid.y);this.gesture={type:'pinch',distance:Math.max(1,Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)),zoom:this.z,ux:(q.x-this.x)/this.z,uy:(q.y-this.y)/this.z};this.suppressTap=true;}else if(p.length===1)this.gesture={type:'drag',sx:p[0].x,sy:p[0].y,x:this.x,y:this.y,moved:false};else this.gesture=null;}
 down(e){if(e.target.closest('button')||!this.enabled()||e.button>0)return;e.preventDefault();this.root.focus({preventScroll:true});if(!this.points.size)this.suppressTap=false;this.points.set(e.pointerId,{x:e.clientX,y:e.clientY});this.root.setPointerCapture(e.pointerId);this.begin();}
 move(e){if(!this.points.has(e.pointerId)||!this.gesture)return;this.points.set(e.pointerId,{x:e.clientX,y:e.clientY});const g=this.gesture,p=[...this.points.values()];if(g.type==='pinch'&&p.length>=2){const q=this.local((p[0].x+p[1].x)/2,(p[0].y+p[1].y)/2);this.z=Math.max(1,Math.min(this.maxZoom,g.zoom*Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)/g.distance));this.x=q.x-g.ux*this.z;this.y=q.y-g.uy*this.z;this.apply();}else if(g.type==='drag'){const dx=e.clientX-g.sx,dy=e.clientY-g.sy;if(Math.hypot(dx,dy)>5){g.moved=true;this.suppressTap=true;this.root.classList.add('dragging');}if(g.moved){this.x=g.x+dx;this.y=g.y+dy;this.apply();}}}
 up(e){if(!this.points.has(e.pointerId))return;const tap=this.points.size===1&&!this.suppressTap&&!this.gesture?.moved;this.points.delete(e.pointerId);if(this.root.hasPointerCapture(e.pointerId))this.root.releasePointerCapture(e.pointerId);this.root.classList.remove('dragging');this.begin();if(tap&&this.enabled())this.onInspect(e.clientX,e.clientY);}
 cancel(e){if(!this.points.has(e.pointerId))return;this.points.delete(e.pointerId);this.suppressTap=true;this.root.classList.remove('dragging');this.begin();}
 get state(){return {zoom:this.z,panX:this.x,panY:this.y};}
}
window.MapNavigation=MapNavigation;
